 if(request.method!=='POST'||url.pathname!=='/api/rooms')fail(405,'Method not allowed.');if(Number(request.headers.get('Content-Length')||0)>200000)fail(413,'Request too large.');const raw=await request.text();if(raw.length>80000)fail(413,'Request too large.');let body;try{body=JSON.parse(raw)}catch{fail(400,'Invalid request.')}if(!body||typeof body!=='object'||Array.isArray(body))fail(400,'Invalid request.');
 if(body.action==='create'){
  await checkRate(env,request,'create',5);if(body.adult!==true)fail(400,'Every player must confirm they are an adult.');const name=nickname(body.name),newToken=randomToken(),id=crypto.randomUUID(),now=Date.now();const r={code:roomCode(),hostId:id,hostActive:now,mode:'friends',players:[{id,name,tokenHash:await hash(newToken),score:0,role:'player',lastSeen:now}],phase:'lobby',locked:false,used:{},round:0,answers:{},ready:[],expiresAt:now+24*3600000};normalize(r);await env.DB.prepare('DELETE FROM rooms WHERE expires_at < ?').bind(now).run();await env.DB.prepare('DELETE FROM room_limits WHERE expires_at < ?').bind(now).run();for(let i=0;i<4;i++){try{await env.DB.prepare('INSERT INTO rooms (code, state, version, created_at, expires_at) VALUES (?, ?, 0, ?, ?)').bind(r.code,JSON.stringify(r),now,r.expiresAt).run();return json({token:newToken,room:publicRoom(r,r.players[0],0)},201)}catch(err){if(!String(err).includes('UNIQUE'))throw err;r.code=roomCode()}}fail(503,'Could not create a code. Try again.');
 }
 if(body.action==='join'){
  await checkRate(env,request,'join',40);if(body.adult!==true)fail(400,'Confirm you are an adult.');if(!/^[A-Z2-9]{6}$/.test(code))fail(400,'Enter a valid room code.');const name=nickname(body.name),newToken=randomToken(),newHash=await hash(newToken),role=body.spectator===true?'spectator':'player';for(let i=0;i<8;i++){const row=await getRow(env,code),r=JSON.parse(row.state);normalize(r);if(role==='spectator'?!r.allowSpectators:(r.locked||r.phase!=='lobby'))fail(409,role==='spectator'?'Spectators are disabled.':'This room is locked or already playing. Ask the host to reopen the lobby.');if(role==='player'?active(r).length>=12:r.players.filter(p=>p.role==='spectator').length>=20)fail(409,'This room is full.');if(r.players.some(p=>p.name.toLowerCase()===name.toLowerCase()))fail(409,'That nickname is already in the room. Choose another.');const p={id:crypto.randomUUID(),name,tokenHash:newHash,score:0,role,lastSeen:Date.now()};r.players.push(p);const result=await env.DB.prepare('UPDATE rooms SET state = ?, version = version + 1 WHERE code = ? AND version = ?').bind(JSON.stringify(r),code,row.version).run();if(result.meta.changes)return json({token:newToken,room:publicRoom(r,p,row.version+1)},201)}fail(409,'Room changed. Try joining again.');
 }
